<?php

declare(strict_types=1);

require_once __DIR__.'/StorageService.php';
require_once __DIR__.'/PerformerQuery.php';

final class PlaybillEnhancementService
{
    public static function castProfiles(PDO $db,int $productionId):array
    {
        $s=$db->prepare("SELECT pm.user_id,pm.participation_role,COALESCE(sp.preferred_name,CONCAT(u.first_name,' ',u.last_name)) display_name,sp.short_bio,sp.headshot_stored_file_id FROM production_memberships pm JOIN users u ON u.id=pm.user_id AND u.active=1 AND u.account_status<>'disabled' LEFT JOIN student_profiles sp ON sp.user_id=u.id LEFT JOIN production_casting_records cr ON cr.production_membership_id=pm.id AND cr.production_id=pm.production_id WHERE pm.production_id=:production AND pm.status='active' AND pm.audience_type IN ('student','adult') AND ".PerformerQuery::membership('pm','u')." ORDER BY pm.participation_role,u.last_name,u.first_name");$s->execute(['production'=>$productionId]);return$s->fetchAll();
    }

    public static function syncCastProfiles(PDO $db,int $playbillId,int $productionId,int $actorId):void
    {
        $q=$db->prepare('SELECT lifecycle_stage FROM productions WHERE id=?');$q->execute([$productionId]);
        if(in_array($q->fetchColumn(),['completed','archived'],true))return; // Frozen historical snapshots are not resynchronized.
        $s=$db->prepare("INSERT INTO playbill_cast_profiles (playbill_id,user_id,display_name,role_title,biography,headshot_stored_file_id,photographer_credit,display_order,visible,approval_status,updated_by_user_id) SELECT :playbill,pm.user_id,COALESCE(NULLIF(sp.preferred_name,''),CONCAT(u.first_name,' ',u.last_name)),COALESCE(NULLIF(cr.role_title,''),pm.participation_role),sp.short_bio,sp.headshot_stored_file_id,sp.photographer_credit,COALESCE((SELECT MAX(existing.display_order)+10 FROM playbill_cast_profiles existing WHERE existing.playbill_id=:playbill_order),10),0,'draft',:actor FROM production_memberships pm JOIN users u ON u.id=pm.user_id AND u.active=1 AND u.account_status<>'disabled' LEFT JOIN student_profiles sp ON sp.user_id=u.id LEFT JOIN production_casting_records cr ON cr.production_membership_id=pm.id AND cr.production_id=pm.production_id WHERE pm.production_id=:production AND pm.status='active' AND pm.audience_type IN ('student','adult') AND ".PerformerQuery::membership('pm','u')." ON DUPLICATE KEY UPDATE role_title=COALESCE(playbill_cast_profiles.role_title,VALUES(role_title))");
        $s->execute(['playbill'=>$playbillId,'playbill_order'=>$playbillId,'actor'=>$actorId,'production'=>$productionId]);
        $s=$db->prepare("INSERT INTO playbill_manual_profiles (playbill_id,manual_credit_id,display_name,role_title,participant_type,biography,headshot_stored_file_id,display_order,visible,approve_public_name,approve_public_biography,approve_public_headshot,updated_by_user_id) SELECT :playbill,mpc.id,COALESCE(NULLIF(mp.display_name,''),CONCAT(mp.first_name,' ',mp.last_name)),mpc.role_title,mpc.participant_type,mp.biography,mp.headshot_stored_file_id,mpc.display_order,mpc.approve_public_name,mpc.approve_public_name,mpc.approve_public_biography,mpc.approve_public_headshot,:actor FROM manual_participant_credits mpc JOIN manual_participants mp ON mp.id=mpc.manual_participant_id AND mp.status='active' WHERE mpc.production_id=:production AND mpc.active=1 ON DUPLICATE KEY UPDATE role_title=VALUES(role_title),participant_type=VALUES(participant_type)");
        $s->execute(['playbill'=>$playbillId,'actor'=>$actorId,'production'=>$productionId]);
    }

    public static function playbillCastProfiles(PDO $db,int $playbillId):array
    {
        $s=$db->prepare("SELECT pcp.*,CONCAT(u.first_name,' ',u.last_name) legal_name,sp.preferred_name master_preferred_name,sp.short_bio master_bio,sp.headshot_stored_file_id master_headshot_id,'registered' identity_type,pcp.user_id identity_id,'cast' participant_type FROM playbill_cast_profiles pcp JOIN users u ON u.id=pcp.user_id LEFT JOIN student_profiles sp ON sp.user_id=pcp.user_id WHERE pcp.playbill_id=:playbill UNION ALL SELECT pmp.id,pmp.playbill_id,-pmp.manual_credit_id user_id,pmp.display_name,pmp.role_title,pmp.biography,pmp.headshot_stored_file_id,NULL photographer_credit,pmp.display_order,pmp.visible,IF(pmp.approve_public_name=1,'approved','draft') approval_status,NULL approved_by_user_id,NULL approved_at,pmp.updated_by_user_id,pmp.created_at,pmp.updated_at,pmp.display_name legal_name,NULL master_preferred_name,NULL master_bio,NULL master_headshot_id,'manual' identity_type,pmp.manual_credit_id identity_id,pmp.participant_type FROM playbill_manual_profiles pmp WHERE pmp.playbill_id=:playbill2 ORDER BY display_order,display_name");$s->execute(['playbill'=>$playbillId,'playbill2'=>$playbillId]);return$s->fetchAll();
    }

    public static function saveManualCastProfile(PDO $db,int $playbillId,int $creditId,int $actorId,array $input):void
    {
        $name=trim((string)($input['display_name']??''));$role=trim((string)($input['role_title']??''));$bio=trim((string)($input['biography']??''));if($name===''||mb_strlen($name)>190||mb_strlen($role)>500||mb_strlen($bio)>5000)throw new RuntimeException('Check the manual participant field lengths.');$check=$db->prepare('SELECT id FROM playbill_manual_profiles WHERE playbill_id=:playbill AND manual_credit_id=:credit');$check->execute(['playbill'=>$playbillId,'credit'=>$creditId]);if(!$check->fetchColumn())throw new RuntimeException('That manual participant is not part of this Playbill.');$s=$db->prepare('UPDATE playbill_manual_profiles SET display_name=:name,role_title=:role,biography=:bio,display_order=:sort,visible=:visible,updated_by_user_id=:actor WHERE playbill_id=:playbill AND manual_credit_id=:credit');$s->execute(['name'=>$name,'role'=>$role?:null,'bio'=>$bio?:null,'sort'=>(int)($input['display_order']??0),'visible'=>!empty($input['visible'])?1:0,'actor'=>$actorId,'playbill'=>$playbillId,'credit'=>$creditId]);self::audit($db,$actorId,'playbill.manual_profile_updated','manual_participant_credit',$creditId,'Updated manual participant Playbill snapshot.',['playbill_id'=>$playbillId]);
    }

    public static function saveCastProfile(PDO $db,string $root,int $playbillId,int $userId,int $actorId,array $input,array $upload):void
    {
        $s=$db->prepare('SELECT * FROM playbill_cast_profiles WHERE playbill_id=:playbill AND user_id=:user FOR UPDATE');$db->beginTransaction();$stored=null;try{$s->execute(['playbill'=>$playbillId,'user'=>$userId]);$row=$s->fetch();if(!$row)throw new RuntimeException('That cast member is not part of this Playbill.');$name=trim((string)($input['display_name']??''));$role=trim((string)($input['role_title']??''));$bio=trim((string)($input['biography']??''));$credit=trim((string)($input['photographer_credit']??''));if($name===''||mb_strlen($name)>190||mb_strlen($role)>190||mb_strlen($credit)>190||mb_strlen($bio)>3000)throw new RuntimeException('Check the cast profile field lengths.');$headshot=$row['headshot_stored_file_id'];if((int)($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$stored=StorageService::store($db,$root,$actorId,$upload);if(!str_starts_with((string)$stored['mime_type'],'image/'))throw new RuntimeException('Headshots must be JPG, PNG, or WebP images.');$headshot=(int)$stored['stored_file_id'];}$visible=!empty($input['visible'])?1:0;$approval=$row['approval_status']==='approved'&&$name===$row['display_name']&&$role===(string)$row['role_title']&&$bio===(string)$row['biography']&&(int)$headshot===(int)$row['headshot_stored_file_id']?'approved':'pending';if(!$visible)$approval='draft';$q=$db->prepare("UPDATE playbill_cast_profiles SET display_name=:name,role_title=:role,biography=:bio,headshot_stored_file_id=:headshot,photographer_credit=:credit,display_order=:sort,visible=:visible,approval_status=:approval,approved_by_user_id=IF(:approval2='approved',approved_by_user_id,NULL),approved_at=IF(:approval3='approved',approved_at,NULL),updated_by_user_id=:actor WHERE playbill_id=:playbill AND user_id=:user");$q->execute(['name'=>$name,'role'=>$role!==''?$role:null,'bio'=>$bio!==''?$bio:null,'headshot'=>$headshot?:null,'credit'=>$credit!==''?$credit:null,'sort'=>(int)($input['display_order']??0),'visible'=>$visible,'approval'=>$approval,'approval2'=>$approval,'approval3'=>$approval,'actor'=>$actorId,'playbill'=>$playbillId,'user'=>$userId]);self::audit($db,$actorId,'playbill.cast_profile_updated','playbill_cast_profile',(int)$row['id'],'Updated production-specific cast profile.',['playbill_id'=>$playbillId,'student_user_id'=>$userId,'approval_status'=>$approval]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($stored&&isset($stored['absolute_path']))@unlink((string)$stored['absolute_path']);throw $e instanceof RuntimeException?$e:new RuntimeException('The cast profile could not be saved.');}
    }

    public static function pendingApprovalsForStudent(PDO $db,int $studentId):array
    {
        $s=$db->prepare("SELECT pcp.*,pb.display_title,p.title production_title FROM playbill_cast_profiles pcp JOIN playbills pb ON pb.id=pcp.playbill_id JOIN productions p ON p.id=pb.production_id WHERE pcp.user_id=:student AND pcp.visible=1 AND pcp.approval_status IN ('pending','approved') ORDER BY p.title");$s->execute(['student'=>$studentId]);return$s->fetchAll();
    }

    public static function decideCastApproval(PDO $db,array $actor,int $profileId,string $decision):void
    {
        if(!in_array($decision,['approved','withdrawn'],true))throw new RuntimeException('Choose approve or withdraw.');$s=$db->prepare('SELECT id,user_id,playbill_id FROM playbill_cast_profiles WHERE id=:id');$s->execute(['id'=>$profileId]);$row=$s->fetch();if(!$row)throw new RuntimeException('That Playbill profile is unavailable.');require_once __DIR__.'/StudentProfileService.php';if(!IdentityRolePolicy::isStudent($db,(int)$row['user_id'])&&(int)$actor['id']!==(int)$row['user_id'])throw new RuntimeException('The Adult performer must review their own publication consent.');if(!StudentProfileService::canEdit($db,$actor,(int)$row['user_id']))throw new RuntimeException('You cannot approve that performer publication profile.');$db->prepare('UPDATE playbill_cast_profiles SET approval_status=:status,approved_by_user_id=:actor,approved_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['status'=>$decision,'actor'=>(int)$actor['id'],'id'=>$profileId]);self::audit($db,(int)$actor['id'],'playbill.cast_consent_'.$decision,'playbill_cast_profile',$profileId,$decision==='approved'?'Approved performer Playbill publication.':'Withdrew performer Playbill publication consent.',['student_user_id'=>(int)$row['user_id'],'playbill_id'=>(int)$row['playbill_id']]);
    }

    public static function publicCastProfiles(PDO $db,int $playbillId):array
    {
        $s=$db->prepare("SELECT pcp.*,'registered' identity_type,pcp.user_id identity_id,'headshot' asset_kind,'cast' participant_type FROM playbill_cast_profiles pcp JOIN users u ON u.id=pcp.user_id AND u.active=1 AND u.account_status<>'disabled' WHERE pcp.playbill_id=:playbill AND pcp.visible=1 AND pcp.approval_status='approved' UNION ALL SELECT pmp.id,pmp.playbill_id,0 user_id,pmp.display_name,pmp.role_title,IF(pmp.approve_public_biography=1,pmp.biography,NULL) biography,IF(pmp.approve_public_headshot=1,pmp.headshot_stored_file_id,NULL) headshot_stored_file_id,NULL photographer_credit,pmp.display_order,pmp.visible,'approved' approval_status,NULL approved_by_user_id,NULL approved_at,pmp.updated_by_user_id,pmp.created_at,pmp.updated_at,'manual' identity_type,pmp.manual_credit_id identity_id,'manual-headshot' asset_kind,pmp.participant_type FROM playbill_manual_profiles pmp JOIN manual_participant_credits mpc ON mpc.id=pmp.manual_credit_id AND mpc.active=1 JOIN manual_participants mp ON mp.id=mpc.manual_participant_id AND mp.status='active' WHERE pmp.playbill_id=:playbill2 AND pmp.visible=1 AND pmp.approve_public_name=1 ORDER BY display_order,display_name");$s->execute(['playbill'=>$playbillId,'playbill2'=>$playbillId]);return$s->fetchAll();
    }

    public static function sponsors(PDO $db,int $playbillId):array
    {
        $s=$db->prepare("SELECT s.*,ps.placement_label,ps.placement_format,ps.sort_order,ps.active attachment_active FROM playbill_sponsors ps JOIN sponsors s ON s.id=ps.sponsor_id WHERE ps.playbill_id=:playbill ORDER BY ps.sort_order,s.name");$s->execute(['playbill'=>$playbillId]);return$s->fetchAll();
    }
    public static function sponsorLibrary(PDO $db):array{return$db->query("SELECT * FROM sponsors WHERE status='active' ORDER BY name")->fetchAll();}

    public static function saveArtwork(PDO $db,string $root,int $playbillId,int $actorId,array $upload):void
    {
        $stored=null;$db->beginTransaction();try{$stored=StorageService::store($db,$root,$actorId,$upload);if(!str_starts_with((string)$stored['mime_type'],'image/'))throw new RuntimeException('Production artwork must be JPG, PNG, or WebP.');$db->prepare('UPDATE playbills SET artwork_stored_file_id=:file WHERE id=:id')->execute(['file'=>(int)$stored['stored_file_id'],'id'=>$playbillId]);self::audit($db,$actorId,'playbill.artwork_updated','playbill',$playbillId,'Updated Playbill production artwork.',[]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($stored&&isset($stored['absolute_path'])&&is_file((string)$stored['absolute_path']))@unlink((string)$stored['absolute_path']);throw $e instanceof RuntimeException?$e:new RuntimeException('The production artwork could not be saved.');}
    }

    public static function saveSponsor(PDO $db,string $root,int $actorId,array $input,array $logoUpload,array $adUpload):int
    {
        $id=(int)($input['sponsor_id']??0);$name=trim((string)($input['sponsor_name']??''));$tier=(string)($input['tier']??'regular');$url=trim((string)($input['website_url']??''));$description=trim((string)($input['public_description']??''));$cta=trim((string)($input['cta_label']??''));$email=trim((string)($input['internal_contact_email']??''));if($name===''||mb_strlen($name)>190||!in_array($tier,['premium','regular'],true))throw new RuntimeException('Enter a sponsor name and valid tier.');if($url!==''&&!filter_var($url,FILTER_VALIDATE_URL))throw new RuntimeException('Enter a valid sponsor website URL.');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid internal contact email.');$files=[];$db->beginTransaction();try{$existing=null;if($id){$q=$db->prepare('SELECT * FROM sponsors WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);$existing=$q->fetch();if(!$existing)throw new RuntimeException('That sponsor could not be found.');}$logo=$existing['logo_stored_file_id']??null;$ad=$existing['advertisement_stored_file_id']??null;foreach([['upload'=>$logoUpload,'field'=>'logo'],['upload'=>$adUpload,'field'=>'ad']] as $candidate){if((int)($candidate['upload']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)continue;$stored=StorageService::store($db,$root,$actorId,$candidate['upload']);if(!str_starts_with((string)$stored['mime_type'],'image/'))throw new RuntimeException('Sponsor artwork must be JPG, PNG, or WebP.');$files[]=$stored;if($candidate['field']==='logo')$logo=(int)$stored['stored_file_id'];else$ad=(int)$stored['stored_file_id'];}$params=['name'=>$name,'tier'=>$tier,'url'=>$url?:null,'description'=>$description?:null,'blurb'=>$description?:null,'logo'=>$logo,'ad'=>$ad,'cta'=>$cta?:null,'contact_name'=>trim((string)($input['internal_contact_name']??''))?:null,'contact_email'=>$email?:null,'contact_phone'=>trim((string)($input['internal_contact_phone']??''))?:null,'notes'=>trim((string)($input['internal_notes']??''))?:null,'starts'=>trim((string)($input['sponsorship_starts_on']??''))?:null,'ends'=>trim((string)($input['sponsorship_ends_on']??''))?:null,'status'=>(string)($input['status']??'active')==='archived'?'archived':'active'];if($id){$params['id']=$id;$sql='UPDATE sponsors SET name=:name,tier=:tier,website_url=:url,public_description=:description,blurb=:blurb,logo_stored_file_id=:logo,advertisement_stored_file_id=:ad,cta_label=:cta,internal_contact_name=:contact_name,internal_contact_email=:contact_email,internal_contact_phone=:contact_phone,internal_notes=:notes,sponsorship_starts_on=:starts,sponsorship_ends_on=:ends,status=:status WHERE id=:id';$event='playbill.sponsor_updated';}else{$params['actor']=$actorId;$sql='INSERT INTO sponsors (name,tier,website_url,public_description,blurb,logo_stored_file_id,advertisement_stored_file_id,cta_label,internal_contact_name,internal_contact_email,internal_contact_phone,internal_notes,sponsorship_starts_on,sponsorship_ends_on,status,created_by_user_id) VALUES (:name,:tier,:url,:description,:blurb,:logo,:ad,:cta,:contact_name,:contact_email,:contact_phone,:notes,:starts,:ends,:status,:actor)';$event='playbill.sponsor_created';}$db->prepare($sql)->execute($params);if(!$id)$id=(int)$db->lastInsertId();self::audit($db,$actorId,$event,'sponsor',$id,$existing?'Updated reusable sponsor.':'Created reusable sponsor.',['name'=>$name,'tier'=>$tier]);$db->commit();return$id;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();foreach($files as $stored)if(isset($stored['absolute_path']))@unlink((string)$stored['absolute_path']);throw $e instanceof RuntimeException?$e:new RuntimeException('The sponsor could not be saved.');}
    }

    public static function attachSponsor(PDO $db,int $playbillId,int $sponsorId,string $placement,int $sortOrder,int $actorId,string $format='card'):void
    {
        if(!in_array($format,['card','half_page','full_page'],true))$format='card';$s=$db->prepare("SELECT 1 FROM sponsors WHERE id=:id AND status='active'");$s->execute(['id'=>$sponsorId]);if(!$s->fetchColumn())throw new RuntimeException('Choose an active sponsor.');$q=$db->prepare("INSERT INTO playbill_sponsors (playbill_id,sponsor_id,placement_label,placement_format,sort_order,active) VALUES (:playbill,:sponsor,:placement,:format,:sort,1) ON DUPLICATE KEY UPDATE placement_label=VALUES(placement_label),placement_format=VALUES(placement_format),sort_order=VALUES(sort_order),active=1");$q->execute(['playbill'=>$playbillId,'sponsor'=>$sponsorId,'placement'=>trim($placement)!==''?trim($placement):null,'format'=>$format,'sort'=>$sortOrder]);self::audit($db,$actorId,'playbill.sponsor_attached','playbill',$playbillId,'Added sponsor to Playbill.',['sponsor_id'=>$sponsorId]);
    }

    public static function removeSponsor(PDO $db,int $playbillId,int $sponsorId,int $actorId):void{$s=$db->prepare('UPDATE playbill_sponsors SET active=0 WHERE playbill_id=:playbill AND sponsor_id=:sponsor');$s->execute(['playbill'=>$playbillId,'sponsor'=>$sponsorId]);if(!$s->rowCount())throw new RuntimeException('That sponsor is not attached to this Playbill.');self::audit($db,$actorId,'playbill.sponsor_removed','playbill',$playbillId,'Removed sponsor from Playbill without deleting the sponsor record.',['sponsor_id'=>$sponsorId]);}

    public static function publicAsset(PDO $db,string $slug,string $kind,int $id):?array
    {
        $p=$db->prepare("SELECT pb.id,pb.production_id,pb.artwork_stored_file_id FROM playbills pb WHERE pb.public_slug=:slug AND pb.public_enabled=1 AND pb.editorial_status IN ('published','archived') LIMIT 1");$p->execute(['slug'=>$slug]);$playbill=$p->fetch();if(!$playbill)return null;$fileId=null;
        if($kind==='artwork')$fileId=$playbill['artwork_stored_file_id']?(int)$playbill['artwork_stored_file_id']:null;
        elseif($kind==='headshot'){$s=$db->prepare("SELECT pcp.headshot_stored_file_id FROM playbill_cast_profiles pcp JOIN users u ON u.id=pcp.user_id AND u.active=1 AND u.account_status<>'disabled' WHERE pcp.playbill_id=:playbill AND pcp.user_id=:user AND pcp.visible=1 AND pcp.approval_status='approved' LIMIT 1");$s->execute(['playbill'=>(int)$playbill['id'],'user'=>$id]);$fileId=(int)($s->fetchColumn()?:0)?:null;}
        elseif($kind==='manual-headshot'){$s=$db->prepare("SELECT pmp.headshot_stored_file_id FROM playbill_manual_profiles pmp JOIN manual_participant_credits mpc ON mpc.id=pmp.manual_credit_id AND mpc.active=1 JOIN manual_participants mp ON mp.id=mpc.manual_participant_id AND mp.status='active' WHERE pmp.playbill_id=:playbill AND pmp.manual_credit_id=:credit AND pmp.visible=1 AND pmp.approve_public_name=1 AND pmp.approve_public_headshot=1 LIMIT 1");$s->execute(['playbill'=>(int)$playbill['id'],'credit'=>$id]);$fileId=(int)($s->fetchColumn()?:0)?:null;}
        elseif(in_array($kind,['sponsor','sponsor-ad'],true)){$column=$kind==='sponsor-ad'?'advertisement_stored_file_id':'logo_stored_file_id';$s=$db->prepare("SELECT s.$column FROM playbill_sponsors ps JOIN sponsors s ON s.id=ps.sponsor_id AND s.status='active' WHERE ps.playbill_id=:playbill AND ps.active=1 AND s.id=:sponsor LIMIT 1");$s->execute(['playbill'=>(int)$playbill['id'],'sponsor'=>$id]);$fileId=(int)($s->fetchColumn()?:0)?:null;}
        return$fileId?StorageService::currentVersion($db,$fileId):null;
    }

    private static function audit(PDO $db,int $actor,string $event,string $type,int $id,string $summary,array $metadata):void{$s=$db->prepare('INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,:type,:id,:summary,:meta)');$s->execute(['actor'=>$actor,'event'=>$event,'type'=>$type,'id'=>$id,'summary'=>$summary,'meta'=>json_encode($metadata,JSON_THROW_ON_ERROR)]);}
}
